<script setup>
import { computed, reactive, ref, watch, nextTick, onBeforeUnmount } from 'vue';
import { useRoute } from 'vue-router';
import { api, auth } from '../services/auth.js';
import ModelConfiguration from '../components/portal/ModelConfiguration.vue';
import ReviewIcon from '../components/portal/ReviewIcon.vue';
const route=useRoute(), section=computed(()=>route.params.section);
const titles={users:'账号管理',roles:'角色权限',model:'模型配置'};
const rows=ref([]), total=ref(0), page=ref(1), pageSize=ref(10), query=ref(''), status=ref(''), loading=ref(false), busy=ref(false), error=ref(''), notice=ref(''), roles=ref([]), catalog=ref({}), modal=ref(false), readonly=ref(false), selected=ref(null), deleting=ref(null), form=reactive({});
const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)));
const groups=computed(()=>Object.entries(catalog.value).reduce((result,[code,label])=>{const parts=label.split(/[:：]/),name=parts.length>1?parts.shift():'数据范围';(result[name] ||= []).push({code,label:parts.join('：').trim()});return result;},{}));
let requestId=0;
function reset(row={}){for(const key of Object.keys(form))delete form[key];Object.assign(form,section.value==='users'?{username:'',name:'',active:true,role_ids:[],password:''}:section.value==='roles'?{name:'',description:'',permissions:[]}:{base_url:'',model_name:'',api_key:'',max_retries:3},JSON.parse(JSON.stringify(row)));}
async function load(){const id=++requestId,current=section.value;if(!titles[current]||current==='model')return;loading.value=true;error.value='';try{const params=new URLSearchParams({page:page.value,page_size:pageSize.value,q:query.value.trim()});if(current==='users')params.set('status',status.value);const data=await api('/api/admin/'+current+(current==='model'?'':'?'+params));if(id!==requestId)return;if(current==='model')reset(data);else{rows.value=data.items||[];total.value=data.total??rows.value.length;catalog.value=data.catalog||{};roles.value=data.role_options||[];if(page.value>pages.value){page.value=pages.value;await load();}}}catch(e){if(id===requestId)error.value=e.message;}finally{if(id===requestId)loading.value=false;}}
function open(row=null,view=false){selected.value=row?.id||null;readonly.value=view;error.value='';reset(row||{});modal.value=true;}
function close(){if(!busy.value){modal.value=false;deleting.value=null;error.value='';}}
function search(){page.value=1;load();}
function go(next){if(next<1||next>pages.value||loading.value)return;page.value=next;load();}
function roleNames(row){return row.role_ids.map(id=>roles.value.find(role=>role.id===id)?.name||id);}
function toggle(items,event){const codes=items.map(item=>item.code);form.permissions=event.target.checked?[...new Set([...form.permissions,...codes])]:form.permissions.filter(code=>!codes.includes(code));}
async function save(){busy.value=true;error.value='';try{const body={...form};if(!body.password)delete body.password;await api('/api/admin/'+section.value+(selected.value&&section.value!=='model'?'/'+selected.value:''),selected.value||section.value==='model'?'PUT':'POST',body);modal.value=false;await load();notice.value='更改已保存';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function remove(){busy.value=true;error.value='';try{await api('/api/admin/'+section.value+'/'+deleting.value.id,'DELETE');deleting.value=null;await load();notice.value='已删除';}catch(e){error.value=e.message;}finally{busy.value=false;}}
function escape(event){if(event.key==='Escape')close();if(event.key==='Tab'){const items=[...event.currentTarget.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
watch(()=>route.params.section,()=>{modal.value=false;deleting.value=null;page.value=1;query.value='';status.value='';notice.value='';reset();load();},{immediate:true});
watch([modal,deleting],async([edit,del])=>{document.body.style.overflow=edit||del?'hidden':'';if(edit||del){await nextTick();document.querySelector('.admin-dialog-close')?.focus();}});
onBeforeUnmount(()=>{document.body.style.overflow='';});
</script>
<template>
<section class="admin-page">
  <header class="admin-heading"><div><div class="admin-kicker">系统设置</div><h1>{{ titles[section] }}</h1><p>{{ section==='users'?'管理团队成员与访问权限':section==='roles'?'定义团队角色，精确控制业务权限':'管理工作空间的 AI 模型连接' }}</p></div><button v-if="section!=='model'" class="button primary" @click="open()"><ReviewIcon name="plus"/>新增{{ section==='users'?'账号':'角色' }}</button><span v-else class="admin-global"><i></i>工作空间配置</span></header>
  <p v-if="error&&!modal&&!deleting" role="alert" class="admin-message error">{{ error }}</p><p v-if="notice" role="status" class="admin-message success">{{ notice }}</p>
  <template v-if="section!=='model'">
    <div class="admin-table-panel">
      <form class="admin-toolbar" @submit.prevent="search"><div class="admin-search"><ReviewIcon name="search"/><input v-model="query" :placeholder="section==='users'?'搜索姓名、账号…':'搜索角色名称、说明…'" aria-label="搜索关键词"></div><select v-if="section==='users'" v-model="status" class="admin-select" aria-label="账号状态" @change="search"><option value="">全部状态</option><option value="active">已启用</option><option value="inactive">已停用</option></select><button class="button" :disabled="loading">查询</button><button type="button" class="admin-reset" @click="query='';status='';search()">重置</button><span class="admin-total">{{ total }} 个{{ section==='users'?'账号':'角色' }}</span></form>
      <div class="admin-table-scroll" :aria-busy="loading"><table class="admin-table"><thead><tr><th>{{ section==='users'?'成员':'角色名称' }}</th><th>{{ section==='users'?'账号':'角色说明' }}</th><th>{{ section==='users'?'角色':'权限数量' }}</th><th>{{ section==='users'?'状态':'成员数量' }}</th><th class="actions-heading">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><div class="admin-member"><span class="record-avatar" :class="{role:section==='roles'}"><ReviewIcon v-if="section==='roles'" name="shield"/><template v-else>{{ row.name?.slice(0,1) }}</template></span><strong>{{ row.name }}</strong><span v-if="section==='users'&&row.id===auth.user?.id" class="admin-self">我</span></div></td><td class="admin-secondary">{{ section==='users'?row.username:(row.description||'—') }}</td><td><div v-if="section==='users'" class="admin-tags"><span v-for="name in roleNames(row)" :key="name">{{ name }}</span><span v-if="!row.role_ids.length">未分配</span></div><span v-else class="admin-secondary">{{ row.permissions.length }} 项权限</span></td><td><span v-if="section==='users'" class="admin-state" :class="{inactive:!row.active}"><i></i>{{ row.active?'已启用':'已停用' }}</span><span v-else class="admin-secondary">{{ row.member_count||0 }} 人</span></td><td><div class="admin-actions"><button @click="open(row,true)">查看</button><button @click="open(row)">编辑</button><button class="danger" :disabled="section==='users'?row.id===auth.user?.id:row.id==='administrator'||row.member_count>0" :title="section==='users'&&row.id===auth.user?.id?'不能删除当前账号':section==='roles'&&row.id==='administrator'?'内置管理员角色不可删除':section==='roles'&&row.member_count>0?'请先调整该角色下的成员':''" @click="error='';deleting=row">删除</button></div></td></tr><tr v-if="!rows.length"><td colspan="5" class="admin-empty"><ReviewIcon name="search"/><strong>{{ loading?'正在加载…':'暂无匹配记录' }}</strong><span v-if="!loading">调整查询条件，或新增{{ section==='users'?'账号':'角色' }}</span></td></tr></tbody></table></div>
      <nav class="admin-pagination" aria-label="列表分页"><span>共 {{ total }} 条记录</span><div><select class="admin-select" v-model.number="pageSize" aria-label="每页条数" @change="search"><option :value="10">10 条 / 页</option><option :value="20">20 条 / 页</option><option :value="50">50 条 / 页</option></select><button :disabled="page<=1||loading" @click="go(page-1)" aria-label="上一页">‹</button><span class="admin-page-number">{{ page }}</span><span class="admin-page-count">/ {{ pages }}</span><button :disabled="page>=pages||loading" @click="go(page+1)" aria-label="下一页">›</button></div></nav>
    </div>
  </template>
  <ModelConfiguration v-else />
  <Teleport to="body"><div v-if="modal||deleting" class="admin-overlay" @click.self="close" @keydown="escape"><section class="admin-dialog" :class="{'role-dialog':section==='roles'&&!deleting,'delete-dialog':deleting}" role="dialog" aria-modal="true" aria-labelledby="admin-dialog-title" tabindex="-1"><header class="admin-dialog-header"><div><h2 id="admin-dialog-title">{{ deleting?'删除'+(section==='users'?'账号':'角色'):(readonly?'查看':selected?'编辑':'新增')+(section==='users'?'账号':'角色') }}</h2><p v-if="!deleting">{{ section==='users'?'成员信息与角色分配':'角色信息与业务权限' }}</p></div><button class="admin-dialog-close" aria-label="关闭" @click="close" :disabled="busy" autofocus>×</button></header>
  <p v-if="error" role="alert" class="admin-message error">{{ error }}</p>
  <template v-if="deleting"><div class="admin-delete-content"><p>确定删除「{{ deleting.name }}」吗？</p><small>{{ section==='users'?'删除后该成员将无法登录，已有业务记录保留。':'删除后该角色及其权限配置将被移除。' }}</small></div><footer class="admin-dialog-footer"><button class="button" @click="close" :disabled="busy">取消</button><button class="button delete-button" @click="remove" :disabled="busy">{{ busy?'删除中…':'确认删除' }}</button></footer></template>
  <form v-else @submit.prevent="save"><fieldset class="admin-dialog-body" :disabled="readonly||busy"><div class="admin-fields"><label>{{ section==='users'?'账号':'角色名称' }}<input class="field" v-model="form[section==='users'?'username':'name']" required maxlength="100" :placeholder="section==='users'?'输入登录账号':'例如：法务审核员'"></label><label>{{ section==='users'?'姓名':'角色说明' }}<input class="field" v-model="form[section==='users'?'name':'description']" :required="section==='users'" :maxlength="section==='users'?200:1000" :placeholder="section==='users'?'输入成员姓名':'简述角色职责'"></label></div>
  <template v-if="section==='users'"><label v-if="!readonly">{{ selected?'重置密码':'初始密码' }}<input class="field" v-model="form.password" type="password" autocomplete="new-password" :required="!selected" minlength="12" maxlength="200" :placeholder="selected?'留空保留原密码':'设置至少 12 位密码'"><small>首次登录或重置后，成员需修改密码</small></label><div class="admin-status-row"><div><strong>账号状态</strong><small>{{ form.active?'已启用，可登录系统':'已停用，禁止登录' }}</small></div><label class="admin-toggle"><input type="checkbox" v-model="form.active" aria-label="启用账号"><span></span></label></div><div><h3>分配角色</h3><div class="admin-role-options"><label v-for="role in roles" :key="role.id" :class="{checked:form.role_ids.includes(role.id)}"><input type="checkbox" v-model="form.role_ids" :value="role.id"><ReviewIcon name="shield"/>{{ role.name }}</label></div></div></template>
  <template v-else><div class="permission-heading"><h3>功能权限</h3><span>已选 {{ form.permissions?.length||0 }} / {{ Object.keys(catalog).length }} 项</span></div><div class="permission-table"><div class="permission-table-head"><span>业务模块</span><span>操作权限</span><span>全选</span></div><div v-for="(items,name) in groups" :key="name" class="permission-row"><strong>{{ name }}</strong><div><label v-for="item in items" :key="item.code"><input type="checkbox" v-model="form.permissions" :value="item.code">{{ item.label }}</label></div><input type="checkbox" :aria-label="'全选'+name" :checked="items.every(item=>form.permissions.includes(item.code))" :indeterminate="items.some(item=>form.permissions.includes(item.code))&&!items.every(item=>form.permissions.includes(item.code))" @change="toggle(items,$event)"></div></div></template>
  </fieldset><footer class="admin-dialog-footer"><button type="button" class="button" @click="close" :disabled="busy">{{ readonly?'关闭':'取消' }}</button><button v-if="!readonly" class="button primary" :disabled="busy">{{ busy?'保存中…':'保存'+(selected?'更改':'并创建') }}</button><button v-else type="button" class="button primary" @click="readonly=false">编辑{{ section==='users'?'账号':'角色' }}</button></footer></form>
  </section></div></Teleport>
</section>
</template>
<style src="../styles/system-admin.css"></style>
